<?php
$query=http_build_query($filters);$exporting=!empty($exportMode);
$num=static function($v,$d=0){return number_format((float)$v,$d,',',' ');};
$period=date('d/m/Y',strtotime($filters['start_date'])).' — '.date('d/m/Y',strtotime($filters['end_date']));
$previousPeriod=date('d/m/Y',strtotime($previousFilters['start_date'])).' — '.date('d/m/Y',strtotime($previousFilters['end_date']));
$indicators=[['Réceptions','received_kg','kg','reports/daily'],['Production','produced_kg','kg','reports/production'],['Emballage','packaged_kg','kg','reports/packaging'],['Distribution','distributed_kg','kg','reports/distribution'],['Rendement pondéré','average_yield','%','reports/yield'],['Flux emballé − distribué','net_finished_flow_kg','kg','reports/stocks']];
$activity=$summary['reception_count']+$summary['production_count']+$summary['packaging_count']+$summary['distribution_count'];
$observations=[];
if(!$activity)$observations[]=['Aucune opération validée','Vérifier la période, le site sélectionné et les opérations en attente.','reports/daily'];
if($summary['net_finished_flow_kg']<0)$observations[]=['Les sorties dépassent l’emballage de '.$num(abs($summary['net_finished_flow_kg'])).' kg','Consulter le stock disponible et les transferts avant de planifier les prochaines sorties.','reports/stocks'];
if($summary['production_count']&&$previousSummary['production_count']&&$summary['average_yield']<$previousSummary['average_yield'])$observations[]=['Rendement en recul de '.$num($previousSummary['average_yield']-$summary['average_yield'],1).' points','Examiner les lots et les machines concernés ; la composition de la production peut expliquer une partie de l’écart.','reports/yield'];
if($summary['waste_kg']>0)$observations[]=['Déchets générés : '.$num($summary['waste_kg']).' kg','Examiner leur valorisation et les pertes par lot. Les déchets traités peuvent provenir de périodes antérieures.','reports/waste'];
if(!$observations)$observations[]=['Lecture des volumes de la période','Compléter cette lecture avec les stocks actuels et les contraintes de production. Aucun objectif de performance n’est configuré ici.','reports/stocks'];
?>
<div class="butchery-workspace reports-executive">
<header class="butchery-heading report-print-header"><span class="butchery-heading-icon"><i class="bi bi-graph-up-arrow" aria-hidden="true"></i></span><div><p>Direction · Flux industriels</p><h2>Synthèse de direction</h2><small><?=e($period)?> · <?=e($periodDays)?> jour(s) · Généré le <?=e($generatedAt??date('d/m/Y H:i'))?></small></div></header>
<?php if(!$exporting):?>
