<?php endif;?>
<p class="report-scope">Volumes validés du périmètre sélectionné. Le fournisseur filtre les réceptions ; la machine filtre la production et le traitement des déchets. L’emballage et la distribution restent au périmètre du site et des dates.</p>
<section class="report-decision-grid" aria-label="Points d’attention"><?php foreach($observations as $observation):?><article><h3><?=e($observation[0])?></h3><p><?=e($observation[1])?></p><?php if(!$exporting):?><a href="<?=e(base_url($observation[2].'?'.$query))?>">Examiner les détails <i class="bi bi-arrow-right" aria-hidden="true"></i></a><?php endif;?></article><?php endforeach;?></section>
<section class="report-kpi-grid" aria-label="Indicateurs clés"><?php foreach($indicators as $metric):$missing=$metric[2]==='%'&&!$summary['production_count'];?><article><span><?=e($metric[0])?></span><strong><?=$missing?'—':e($num($summary[$metric[1]],$metric[2]==='%'?1:0).' '.$metric[2])?></strong><?php if($metric[2]==='kg'&&$metric[1]!=='net_finished_flow_kg'):?><small><?=e($num($summary[$metric[1]]/$periodDays))?> kg / jour</small><?php elseif($metric[1]==='net_finished_flow_kg'):?><small>Flux de période, pas un solde de stock</small><?php else:?><small>Sortie ÷ entrée des lots validés</small><?php endif;?></article><?php endforeach;?></section>
<section class="table-panel butchery-history"><header class="fuel-section-heading"><div><h3>Évolution des résultats</h3><small>Comparaison : <?=e($previousPeriod)?> · même durée et mêmes filtres</small></div></header><div class="table-responsive"><table class="enterprise-table" data-datatable="false"><thead><tr><th>Indicateur</th><th>Période</th><th>Précédente</th><th>Écart</th><th>Variation</th><?php if(!$exporting):?><th>Détail</th><?php endif;?></tr></thead><tbody><?php foreach($indicators as $metric):$key=$metric[1];$current=$summary[$key];$before=$previousSummary[$key];$yield=$metric[2]==='%';$missing=$yield&&(!$summary['production_count']||!$previousSummary['production_count']);$delta=$current-$before;?><tr><td><strong><?=e($metric[0])?></strong></td><td><?=($yield&&!$summary['production_count'])?'—':e($num($current,$yield?1:0).' '.$metric[2])?></td><td><?=($yield&&!$previousSummary['production_count'])?'—':e($num($before,$yield?1:0).' '.$metric[2])?></td><td><?=$missing?'—':e(($delta>0?'+':'').$num($delta,$yield?1:0).($yield?' points':' kg'))?></td><td><?=$missing||$yield||$before<=0?'—':e(($delta>0?'+':'').$num($delta/$before*100,1).' %')?></td><?php if(!$exporting):?><td><a class="btn-secondary" href="<?=e(base_url($metric[3].'?'.$query))?>">Consulter</a></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><p class="report-scope">« — » : comparaison non applicable ou base précédente nulle. Une hausse de volume n’indique pas à elle seule une amélioration de performance.</p></section>
<section class="table-panel butchery-history"><header class="fuel-section-heading"><h3>Activité de la période</h3></header><div class="table-responsive"><table class="enterprise-table" data-datatable="false"><thead><tr><th>Activité</th><th>Opérations</th><th>Volume</th></tr></thead><tbody><?php foreach($directionRows as $row):?><tr><td><?=e($row['label'])?></td><td><?=e($num($row['count']))?></td><td><?=e($num($row['quantity']))?> kg</td></tr><?php endforeach;?></tbody></table></div></section>
